-- Remove only obsolete built-in links whose categories no longer exist.
-- Preserve valid categories, user-defined links, content and media.
UPDATE settings SET value=json_set(value,'$.headerNav',json(COALESCE((SELECT json_group_array(json(item.value)) FROM json_each(settings.value,'$.headerNav') item WHERE NOT (json_extract(item.value,'$.href') IN ('/category/virtual-cards/','/category/banking/','/category/brokerage/','/category/ai-tools/','/category/esim-phones/','/category/esim-adapters/','/category/apple-us-id/','/category/cryptocurrency/') AND NOT EXISTS(SELECT 1 FROM categories c WHERE '/category/'||c.slug||'/'=json_extract(item.value,'$.href') AND c.deleted_at IS NULL))),'[]'))),version=version+1 WHERE id=1 AND EXISTS(SELECT 1 FROM json_each(settings.value,'$.headerNav') item WHERE json_extract(item.value,'$.href') IN ('/category/virtual-cards/','/category/banking/','/category/brokerage/','/category/ai-tools/','/category/esim-phones/','/category/esim-adapters/','/category/apple-us-id/','/category/cryptocurrency/') AND NOT EXISTS(SELECT 1 FROM categories c WHERE '/category/'||c.slug||'/'=json_extract(item.value,'$.href') AND c.deleted_at IS NULL));
