UPDATE settings SET value=json_set(value,'$.homeOptions.promoHref','/tutorials/'),version=version+1 WHERE id=1 AND json_extract(value,'$.homeOptions.promoHref') IN ('/category/virtual-cards/','/category/banking/','/category/brokerage/','/category/ai-tools/','/category/esim-phones/','/category/esim-adapters/','/category/apple-us-id/','/category/cryptocurrency/') AND NOT EXISTS(SELECT 1 FROM categories c WHERE '/category/'||c.slug||'/'=json_extract(settings.value,'$.homeOptions.promoHref') AND c.deleted_at IS NULL);
UPDATE settings SET value=json_set(value,'$.notice',''),version=version+1 WHERE id=1 AND json_extract(value,'$.notice')='本地演示站 · 内容与素材待确认后正式上线';
